<!-- wp:kadence/advancedheading {"uniqueID":"7_fc826d-91","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-sm vf-mt-1h"} -->
<p class="kt-adv-heading7_fc826d-91 wp-block-kadence-advancedheading vf-t-sm vf-mt-1h" data-kb-block="kb-adv-heading7_fc826d-91">Visitor IPs aren't stored unless you switch it on.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_23e245-98","kbVersion":2,"className":"vf-card-sm vf-bg-sky70"} -->
<div class="wp-block-kadence-column kadence-column7_23e245-98 vf-card-sm vf-bg-sky70"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_bd3149-0a","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-t-bold"} -->
<h3 class="kt-adv-heading7_bd3149-0a wp-block-kadence-advancedheading vf-t-bold" data-kb-block="kb-adv-heading7_bd3149-0a">WordPress privacy tools</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_569435-51","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-sm vf-mt-1h"} -->
<p class="kt-adv-heading7_569435-51 wp-block-kadence-advancedheading vf-t-sm vf-mt-1h" data-kb-block="kb-adv-heading7_569435-51">Works with Export Personal Data and Erase Personal Data.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_dc6afe-d1","kbVersion":2,"className":"vf-card-sm vf-bg-sky70"} -->
<div class="wp-block-kadence-column kadence-column7_dc6afe-d1 vf-card-sm vf-bg-sky70"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_1f4624-d4","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-t-bold"} -->
<h3 class="kt-adv-heading7_1f4624-d4 wp-block-kadence-advancedheading vf-t-bold" data-kb-block="kb-adv-heading7_1f4624-d4">Policy text, suggested</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_d2a6ff-f4","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-sm vf-mt-1h"} -->
<p class="kt-adv-heading7_d2a6ff-f4 wp-block-kadence-advancedheading vf-t-sm vf-mt-1h" data-kb-block="kb-adv-heading7_d2a6ff-f4">Adds suggested wording to the WordPress privacy policy guide.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column --></div></div>
<!-- /wp:kadence/column --></div></div>
<!-- /wp:kadence/column -->
<!-- /wp:kadence/rowlayout -->

<!-- wp:kadence/rowlayout {"uniqueID":"7_0c9052-01","colLayout":"equal","tabletLayout":"row","align":"full","inheritMaxWidth":true,"padding":[144,"",144,""],"mobilePadding":[112,"",112,""],"kbVersion":2,"className":"vf-k vf-k-top vf-k-faq vf-cols-40"} -->
<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_d2fdd1-bb","kbVersion":2,"className":"vf-reveal"} -->
<div class="wp-block-kadence-column kadence-column7_d2fdd1-bb vf-reveal"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"uniqueID":"7_90e046-eb","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"div","className":"vf-eyebrow"} -->
<div class="kt-adv-heading7_90e046-eb wp-block-kadence-advancedheading vf-eyebrow" data-kb-block="kb-adv-heading7_90e046-eb">FAQ</div>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_4b1b3d-4a","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-t-h2 vf-mt-5"} -->
<h2 class="kt-adv-heading7_4b1b3d-4a wp-block-kadence-advancedheading vf-t-h2 vf-mt-5" data-kb-block="kb-adv-heading7_4b1b3d-4a">Good questions.</h2>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_44d652-7c","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-t-lead vf-mt-5"} -->
<p class="kt-adv-heading7_44d652-7c wp-block-kadence-advancedheading vf-t-lead vf-mt-5" data-kb-block="kb-adv-heading7_44d652-7c">Straight answers, no small print.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"id":2,"borderWidth":["","","",""],"uniqueID":"7_0e5d34-d2","kbVersion":2,"className":"vf-accordion"} -->
<div class="wp-block-kadence-column kadence-column7_0e5d34-d2 vf-accordion"><div class="kt-inside-inner-col"><!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_a1faec-1b","kbVersion":2,"className":"vf-acc-item is-open"} -->
<div class="wp-block-kadence-column kadence-column7_a1faec-1b vf-acc-item is-open"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_8daf2f-0d","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_8daf2f-0d wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_8daf2f-0d">Is there a limit on forms or submissions?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_2f3e16-0f","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_2f3e16-0f wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_2f3e16-0f">No. Build as many forms as you like and collect as many submissions as you get.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_5000b9-37","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_5000b9-37 vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_25a93d-6c","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_25a93d-6c wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_25a93d-6c">Do I need another plugin?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_6073ca-a0","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_6073ca-a0 wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_6073ca-a0">No. VuloForm works by itself. VuloMail is optional — it makes email delivery more reliable and is required for SMS notifications.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_2075df-b5","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_2075df-b5 vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_d0ea17-ae","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_d0ea17-ae wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_d0ea17-ae">Can I put a form on a site that isn't WordPress?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_72ee8e-e9","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_72ee8e-e9 wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_72ee8e-e9">Yes. Copy the snippet under “On another website” on the form's Share tab and paste it into that page's HTML. Your WordPress site must stay online, and the form needs JavaScript on the other site.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_eb15ae-d4","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_eb15ae-d4 vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_997a88-c3","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_997a88-c3 wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_997a88-c3">Is there a CAPTCHA?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_3c52a5-2d","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_3c52a5-2d wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_3c52a5-2d">No. Forms are protected by a hidden trap field, a minimum fill time and a rate limit. Developers can connect another anti-spam service with the vuloform_spam_check filter.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_cac0f9-e0","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_cac0f9-e0 vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_4de10e-26","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_4de10e-26 wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_4de10e-26">Can conditional logic be bypassed?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_29e668-e1","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_29e668-e1 wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_29e668-e1">No. The rules are checked again on your server. A field hidden by its rules is never stored, and a required field can't be skipped by turning off JavaScript.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_86c64e-bc","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_86c64e-bc vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_9589e0-5f","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_9589e0-5f wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_9589e0-5f">Are uploaded files public?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_da33e4-61","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_da33e4-61 wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_da33e4-61">They're stored under long random names in a folder that blocks direct access on Apache and LiteSpeed. Administrators download them through WordPress. On nginx, ask your host to block wp-content/uploads/vuloform/.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_0629b7-af","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_0629b7-af vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_803ed0-ee","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_803ed0-ee wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_803ed0-ee">Does “Handed off” mean the email was delivered?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_aa0ff1-3d","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_aa0ff1-3d wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_aa0ff1-3d">It means your site's mail system accepted it. VuloForm can't see whether it reached the inbox — if mail goes missing, check spam and consider an SMTP plugin such as VuloMail.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column -->

<!-- wp:kadence/column {"borderWidth":["","","",""],"uniqueID":"7_4c165d-06","kbVersion":2,"className":"vf-acc-item"} -->
<div class="wp-block-kadence-column kadence-column7_4c165d-06 vf-acc-item"><div class="kt-inside-inner-col"><!-- wp:kadence/advancedheading {"level":3,"uniqueID":"7_58451b-d7","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"className":"vf-acc-q"} -->
<h3 class="kt-adv-heading7_58451b-d7 wp-block-kadence-advancedheading vf-acc-q" data-kb-block="kb-adv-heading7_58451b-d7">What is removed when I delete the plugin?</h3>
<!-- /wp:kadence/advancedheading -->

<!-- wp:kadence/advancedheading {"uniqueID":"7_71c19d-b5","markBorder":"","markBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"tabletMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"mobileMarkBorderStyles":[{"top":[null,"",""],"right":[null,"",""],"bottom":[null,"",""],"left":[null,"",""],"unit":"px"}],"htmlTag":"p","className":"vf-acc-a"} -->
<p class="kt-adv-heading7_71c19d-b5 wp-block-kadence-advancedheading vf-acc-a" data-kb-block="kb-adv-heading7_71c19d-b5">Nothing, by default, so a reinstall picks up where you left off. To remove everything, choose “Delete everything” under VuloForm › Settings first.</p>
<!-- /wp:kadence/advancedheading --></div></div>
<!-- /wp:kadence/column --></div></div>
<!-- /wp:kadence/column -->
<!-- /wp:kadence/rowlayout -->

<!-- wp:kadence/rowlayout {"uniqueID":"7_581cd6-f8","columns":1,"colLayout":"row","align":"full","inheritMaxWidth":true,"padding":["0","",40,""],"kbVersion":2,"className":"vf-k vf-k-cta"} -->
